sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float strength;
uniform float grain;
uniform float blotches;
uniform float scale;
uniform float burn;
layout(color) uniform half4 color;
uniform float tint;
uniform float seed;
float hash11(float p) {
    p = fract(p * 0.1031);
    p *= p + 33.33;
    p *= p + p;
    return fract(p);
}
float hash21(float2 p) {
    float3 q = fract(float3(p.xyx) * 0.1031);
    q += dot(q, q.yzx + 33.33);
    return fract((q.x + q.y) * q.z);
}
float vnoise(float2 p) {
    float2 i = floor(p);
    float2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash21(i), hash21(i + float2(1, 0)), f.x), mix(hash21(i + float2(0, 1)), hash21(i + float2(1, 1)), f.x), f.y);
}
float fbm(float2 p) {
    float s = 0.0;
    float a = 0.5;
    for (int i = 0; i < 5; i++) {
        s += a * vnoise(p);
        p = p * 2.03 + float2(17.1, 9.7);
        a *= 0.5;
    }
    return s / 0.96875;
}
half4 main(float2 coord) {
    half4 c = image.eval(coord);
    if (c.a <= 0.0) return c;
    float3 base = float3(unpremul(c).rgb);
    float3 rgb = base;
    float sc = max(scale, 4.0);
    float blot = fbm(coord / sc + seed * 17.0);
    float fine = fbm(coord / (sc * 0.3) + seed * 5.0 + 31.0);
    float noise = hash21(floor(coord) + seed * 3.0);
    float haze = smoothstep(0.3, 0.8, blot) * blotches * 0.6 + grain * (noise - 0.2) * 0.55;
    rgb = 1.0 - (1.0 - rgb) * (1.0 - float3(1.0, 0.72, 0.66) * clamp(haze, 0.0, 1.0));
    rgb *= 1.0 - blotches * 0.12 * smoothstep(0.55, 0.2, fine);
    float2 e = min(coord, size - coord);
    float reach = 0.12 * min(size.x, size.y);
    float wall = min(e.x, e.y) + (fine - 0.5) * 0.5 * reach;
    rgb = mix(rgb, rgb * float3(0.3, 0.2, 0.12), burn * (1.0 - smoothstep(0.0, reach, wall)));
    rgb = mix(rgb, float3(color.rgb), tint * float(color.a));
    rgb = mix(base, clamp(rgb, 0.0, 1.0), clamp(strength, 0.0, 1.0));
    return half4(half3(rgb) * c.a, c.a);
}
